def transform(grid):
    g=[r[:] for r in grid]
    bg=g[0][0]
    # Rectangular target blocks are identified by their fill color and border color.
    blocks={}
    for r in range(len(g)):
        if len(set(g[r]))==2 and g[r][0]==g[r][-1] and len(set(g[r][1:-1]))==1:
            fill=g[r][1]
            if fill!=bg:
                blocks.setdefault(fill,[]).append(r)
    for r in range(len(g)):
        for c in range(len(g[0])):
            if r<min((min(v) for v in blocks.values()),default=len(g)):
                g[r][c]=bg
    # Copy every pattern from the header into the block matching its interior.
    header_end=min(min(v) for v in blocks.values())
    for fill,rows in blocks.items():
        border=g[rows[0]][0]
        for r in range(header_end):
            for c in range(len(g[0])):
                if grid[r][c]!=bg and grid[r][c]!=fill:
                    # Pattern interior is the surrounding/header background only when absent.
                    pass
    # Connected components in the header, including multi-color patterns.
    seen=set()
    for r in range(header_end):
        for c in range(len(g[0])):
            if grid[r][c]==bg or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<header_end and 0<=xx<len(g[0]) and grid[yy][xx]!=bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            colors={grid[y][x] for y,x in cells}
            for fill,rows in blocks.items():
                if fill in colors:
                    border=g[rows[0]][0]
                    for y,x in cells:
                        g[y+rows[-1]-max(yy for yy,xx in cells)][x]=border
                    break
    return g

